def lpHaarPartialLevel (𝕜 : Type*) [RCLike 𝕜] (p : BanachExponent) (n : ℕ)
    (S : Finset (Fin (2 ^ n))) : IntervalLp 𝕜 p →L[𝕜] IntervalLp 𝕜 p :=
  ∑ k ∈ S, (lpHaarDyadicCoefficient 𝕜 p n k).smulRight (lpHaarDyadic 𝕜 p n k)

